def binary_search(items, target):
    """Return the index of target in a sorted list, or -1 if not present."""
    low, high = 0, len(items) - 1
    while low <= high:
        mid = (low + high) // 2
        if items[mid] == target:
            return mid
        elif items[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1


if __name__ == "__main__":
    data = [1, 3, 5, 7, 9, 11]
    print(binary_search(data, 7))  # -> 3
    print(binary_search(data, 8))  # -> -1

from collections import Counter


def top_words(text, n=3):
    """Return the n most common words in a piece of text, ignoring case."""
    words = [w.strip(".,!?;:").lower() for w in text.split()]
    words = [w for w in words if w]
    counts = Counter(words)
    return counts.most_common(n)


sample = "The cat sat on the mat. The cat was happy."
for word, count in top_words(sample):
    print(f"{word}: {count}")

class Stack:
    """A simple last-in, first-out stack."""

    def __init__(self):
        self._items = []

    def push(self, item):
        self._items.append(item)

    def pop(self):
        if not self._items:
            raise IndexError("pop from empty stack")
        return self._items.pop()

    def peek(self):
        return self._items[-1] if self._items else None

    def __len__(self):
        return len(self._items)


s = Stack()
for value in (1, 2, 3):
    s.push(value)
print(s.pop(), s.peek(), len(s))  # -> 3 2 2
